function threatStatus(){const rows=[];let level=run.threat;for(const [id,type] of Object.entries(ENEMY_TYPES)){const count=cops.filter(a=>a.alive&&a.unit===id).length;if(count){rows.push('L'+type.threat+' '+type.name+' ×'+count);level=Math.max(level,type.threat);}}const gunships=helis.filter(h=>!h.dead).length,transports=airlifts.flights.filter(h=>!h.dead).length,cars=vehicles.filter(v=>!v.dead&&!v.truck).length,trucks=vehicles.filter(v=>!v.dead&&v.truck).length;if(cars)rows.push('L2 CARS ×'+cars);if(trucks)rows.push('L3 TRUCKS ×'+trucks);if(gunships){rows.push('L4 GUNSHIPS ×'+gunships);level=Math.max(level,4);}if(transports){rows.push('L4 AIRLIFTS ×'+transports);level=Math.max(level,4);}if(reinforcements.counts.tanks){rows.push('L5 TANKS ×'+reinforcements.counts.tanks);level=5;}if(cars)level=Math.max(level,2);if(trucks)level=Math.max(level,3);return {level,rows};}
