 const names=['FREE ROAM','ON FOOT','HOT PURSUIT','HEAVY UNITS','AIR SUPPORT','EXTREME CHAOS'];const danger=threatStatus();$('threatName').textContent='DANGER L'+danger.level+'/5 · '+names[danger.level];$('enemyThreats').textContent=danger.rows.join(' / ');const liveUnits=cops.filter(a=>a.alive);$('threatCount').textContent=run.kills+' KILLS / '+liveUnits.length+' UNITS / '+(helis.length+airlifts.count)+' HELIS / '+new Set(liveUnits.map(a=>a.unit)).size+' TYPES';$('threatCount').title=Object.entries(ENEMY_TYPES).map(([id,t])=>liveUnits.filter(a=>a.unit===id).length+' '+t.name).join(' / ');document.querySelectorAll('#threatBars i').forEach((b,i)=>b.classList.toggle('active',i<danger.level));$('waveWarning').textContent=pending.length?pending[0].label+' IN '+Math.max(1,Math.ceil(pending[0].due-run.elapsed))+'s':'';
 $('combo').classList.toggle('hidden',run.combo<2);$('multiplier').textContent='×'+comboMultiplier().toFixed(1);$('chain').textContent=run.combo+' CHAIN';$('comboName').textContent=run.combo>=24?'ABSOLUTE MENACE':run.combo>=12?'TOTAL MAYHEM':run.combo>=6?'KEEP IT GOING':'NICE START';$('comboFill').style.width=(run.comboTime/Math.min(9,5.5+run.combo*.1)*100)+'%';const next=MILESTONES.find(m=>m.at>run.score),target=next?.at||(Math.floor(run.score/500000)+1)*500000,prev=next?MILESTONES.filter(m=>m.at<next.at).at(-1)?.at||0:target-500000;$('objectiveLabel').textContent='NEXT / '+number(target)+' POINTS';$('objectiveFill').style.width=clamp((run.score-prev)/(target-prev)*100,0,100)+'%';$('objective').textContent=next?.name||(run.siege?'NEXT OVERDRIVE / SIEGE INTENSIFIES':'OVERDRIVE / MILLION POINT SIEGE AT 1M');$('timer').textContent=clock(Math.max(0,Math.ceil(run.duration-run.elapsed)))+' LEFT · '+MODES[run.gameMode].name.toUpperCase()+(run.speedTier?' · ×'+run.escalation.toFixed(2)+' SPEED':'');$('cooldown').style.width=Math.min(38,attackCooldown*55)+'px';
 const aim=aimTarget();$('targetInfo').textContent=aim.entity?((aim.entity.unit?ENEMY_TYPES[aim.entity.unit].name+' L'+ENEMY_TYPES[aim.entity.unit].threat:aim.entity.rotor?'HELICOPTER':aim.entity.alive!==undefined?'CIVILIAN':'VEHICLE')+' / '+Math.ceil(aim.entity.hp)+' HP'):'';if(aim.object){const o=aim.object;$('targetInfo').textContent=o.kind.toUpperCase();const sub=document.createElement('small');sub.textContent=number(o.score)+' PTS · '+money(o.cost)+(o.kind==='elevator'?' · '+Math.ceil(o.hp)+' HP':'');$('targetInfo').appendChild(sub);}aimLine.visible=run.equipped==='rock'&&run.rocks>0;const origin=player.pos.clone().add(V(0,1.35,0)),delta=aim.point.clone().sub(origin),travel=clamp(delta.length()/48,.06,1.9),vel=delta.divideScalar(travel);vel.y+=6*travel;const attr=aimGeometry.attributes.position;for(let i=0;i<18;i++){const t=i/17*Math.min(travel,1.2),p=origin.clone().addScaledVector(vel,t);p.y-=6*t*t;attr.setXYZ(i,p.x,p.y,p.z);}attr.needsUpdate=true;aimGeometry.computeBoundingSphere();
