function beginActive(){if(!run||run.finished)return;mode='playing';run.elapsed=0;accumulator=0;lastTime=performance.now();run.startedHeat=true;if(run.gameMode==='extreme'||run.gameMode==='insane'){player.invincible=run.gameMode==='insane'?3:8;pending=[];run.threat=run.threatReached=5;run.scheduledTiers=new Set([1,2,3,4,5]);spawnCops(10,null,false,'swat');spawnVehicle(false);spawnVehicle(true);spawnHeli();spawnHeli();if(run.gameMode==='insane'){for(let i=2;i<12;i++)spawnHeli();for(const type of SPECIALISTS)spawnCops(2,null,false,type);spawnVehicle(false);spawnVehicle(true);run.nextSwarm=6;}addTrampolines();reinforcements.unleash();run.nextReinforce=config().waves;}else queueThreat(1);audio.unlock();$('hud').classList.remove('hidden');lastVisibility='';updateVisibility();camReady=false;toast(run.gameMode==='insane'?'INSANE / 3s SHIELD / MAXIMUM SPEED':run.gameMode==='extreme'?'8s SPAWN SHIELD / get moving! Q smoke / E service lift.':'F punch / G kick / Q smoke / E service lift. '+settings.matchMinutes+' minutes.',5);requestLock();}
function endRun(banked){if(!run||run.finished)return;$('elevatorStatus').classList.add('hidden');bodyCarry.release();run.finished=true;run.banked=banked;run.died=!player.alive||player.hp<=0;if(run.died)audio.stopMenu();run.earlyArrest=!run.died&&!banked&&run.elapsed<Math.min(90,run.duration*.5);run.deported=run.earlyArrest&&Math.random()<.4;run.cause=banked?(run.timedOut?'the dismissal bell':'score banked'):run.cause||'one bad idea too many';run.endDelay=banked?.2:run.splatted?2.4:1.35;run.rivalBest=Math.max(...rivals.map(a=>a.score));previousResult=finishProfile(run);mode='ending';combat=null;combatCooldown=0;smokeCloud.visible=false;escapeLift.visible=false;paused=false;fireHeld=false;resetKeys();document.exitPointerLock?.();$('panel').classList.add('hidden');$('hud').classList.add('hidden');aimLine.visible=false;viewWeapon.visible=false;playerRing.visible=false;}
function showResults(){mode='results';$('resultCrimes').textContent=caseText(crimeReport(run),run.died);$('results').classList.remove('hidden');$('epilogue').classList.toggle('hidden',run.died);$('endReason').textContent=run.died?'DIED':run.timedOut?'TIME UP':run.banked?'SCORE BANKED':run.earlyArrest?'EARLY ARREST':'CAUGHT';$('grade').textContent=ratingFor(run.score).grade;$('grade').title=RATINGS.map(r=>r.grade+': '+number(r.at)).join(' / ');$('resultHeadline').textContent=run.died?'CISCO DIED.':run.score>=50000?'ABSOLUTE. MAYHEM.':run.banked?'SCHOOL CAN WAIT.':'CLASS DISMISSED.';$('recordLabel').textContent=run.score>previousResult.old?'NEW PERSONAL BEST!':'FINAL SCORE';$('finalScore').textContent=number(run.score);$('comparison').textContent=run.died?'Killed by '+run.cause+'. This ending is final for this run.':run.score>previousResult.old?'+'+number(run.score-previousResult.old)+' above your old record. Thursday will be awkward.':number(previousResult.old-run.score)+' away from your personal best. Run it back.';$('finalDestroyed').textContent=run.destroyed;$('finalCombo').textContent=run.bestCombo+' / ×'+Math.min(5,1+Math.floor(run.bestCombo/3)*.5).toFixed(1);$('finalFloor').textContent=run.highestFloor+' / ∞';$('finalTime').textContent=clock(run.elapsed);$('finalThreat').textContent=run.threatReached+' / 5';$('finalDebt').textContent=money(run.debt);const lines=previousResult.earned.map(a=>'<b>UNLOCKED / '+a.name+'</b> · '+a.reward);lines.push(run.died?'DEATH ENDING / Cisco did not survive. There is no Thursday dismissal.':run.earlyArrest?(run.deported?'BAD ENDING / Cisco and his family were deported. Fictional story branch.':'BAD ENDING / Early arrest. Cisco is held at Avalon Police Station.'):run.arrested?'ARREST / Cisco was taken alive to Avalon Police Station.':'THURSDAY / Mom called. Cisco hesitated. The police arrived at the exit.');lines.push('Ended by: '+run.cause);lines.push(MODES[run.gameMode].name+' / '+run.successfulHits+' combat hits / '+run.kills+' kills / '+run.officersDown+' officers down / '+run.policeEncounters+' encounters');lines.push('Grades: '+RATINGS.map(r=>r.grade+' '+number(r.at)).join(' · '));lines.push(run.windows+' windows · '+run.escapes+' clean getaways · '+run.hazardKills+' hazard assists · '+run.bounces+' bounces');lines.push('Rival best: '+number(Math.max(...rivals.map(a=>a.score)))+' · Your destruction: '+run.destroyed+' / '+run.totalDestroyed+' total objects');$('achievements').innerHTML=lines.map(t=>'<div>'+t+'</div>').join('');}
function mainMenu(){audio.stopMenu();clearRuntime();world.resetTower();physics.syncTower();mode='menu';paused=false;run=null;$('results').classList.add('hidden');$('aftermath').classList.add('hidden');$('hud').classList.add('hidden');$('panel').classList.add('hidden');$('menu').classList.remove('hidden');$('menuBest').textContent=number(profile.best);$('menuDifficulty').textContent=settings.difficulty.toUpperCase()+' PRESSURE';updateVisibility();}
