 await test('Blood persists for the whole round without eviction and uses bounded spray',()=>{newRun();player.invincible=0;const before=fx.counts.bloodStains;hurt(player,5,'a test hit');check(fx.counts.bloodStains===before+1,'hit did not leave blood');hurt(player,5,'a blocked hit');check(fx.counts.bloodStains===before+1,'hit shield spawned blood');for(let i=0;i<600;i++)fx.blood(V(27,1,12));const total=before+601;check(fx.counts.bloodStains===total,'blood stains evicted');check(fx.counts.bloodParticles<=256,'blood spray unbounded');check(scene.children.filter(m=>m.userData.blood).length<=4,'blood draw calls unbounded');fx.clear({keepBlood:true});fx.update(120);check(fx.counts.bloodStains===total,'round stains faded or cleared');newRun();check(fx.counts.bloodStains===0,'blood leaked across runs');return {permanentRoundStains:true,noEviction:true,batchedDrawCalls:4,sprayCap:256,reset:true};});
 await test('High falls splat on impact regardless of shields or enemy health',()=>{newRun();player.pos.set(27,H*4,12);player.mesh.position.copy(player.pos);player.fallTop=player.pos.y;player.vel.set(0,0,0);player.grounded=false;player.invincible=100;for(let i=0;i<240&&player.alive;i++)moveActor(player,1/60,V(),0);check(!player.alive&&player.hp===0&&run.splatted&&run.died,'high fall did not splat');check(player.pos.y===0&&run.cause==='a fatal splat'&&fx.counts.bloodStains>=30,'splat occurred before ground impact or lacked blood');check(player.splatted&&!player.mesh.visible&&!player.rag&&fx.counts.ragdolls===0,'splat retained a body or bones');const stainCount=fx.counts.bloodStains;for(let i=0;i<150;i++)physicsStep(1/60);check(cinematics.active==='death'&&!player.mesh.visible&&fx.counts.bloodStains>=stainCount,'cinematic revived body or erased splat');cinematics.step(19);cinematics.finish();check(!player.mesh.visible&&fx.counts.bloodStains>=stainCount,'results lost splat');newRun();spawnCops(1,null,false,'juggernaut');const a=cops[0];a.pos.set(27,H*5,12);a.mesh.position.copy(a.pos);a.fallTop=a.pos.y;a.vel.set(0,0,0);a.grounded=false;a.invincible=100;for(let i=0;i<240&&a.alive;i++)moveActor(a,1/60,V(),0);check(!a.alive&&a.hp===0&&mode==='playing','high-health enemy survived fall or ended player run');check(a.splatted&&!a.mesh.visible&&!a.rag&&fx.counts.ragdolls===0,'enemy splat retained bones');newRun();player.pos.set(27,H*3,12);player.mesh.position.copy(player.pos);player.fallTop=player.pos.y;player.vel.set(0,0,0);player.grounded=false;player.invincible=0;for(let i=0;i<240&&!player.grounded;i++)moveActor(player,1/60,V(),0);check(player.alive&&player.hp<100&&!run.splatted,'shorter fall splatted instead of normal damage');newRun();return {fatalHeight:H*4,playerAndJuggernaut:true,shieldCannotPrevent:true,noBodyOrBones:true,cinematicPersistence:true,shortFallsStillPlayable:true};});
 await test('SWAT kills unlock stealable rifles; other deaths supply ammo and reset cleanly',()=>{newRun();equip('gun');check(!run.gun&&run.equipped==='rock','rifle unlocked at start');player.pos.set(27,0,12);player.mesh.position.copy(player.pos);spawnCops(1,null,false,'swat');const swat=cops.at(-1);swat.pos.set(27,0,13);swat.mesh.position.copy(swat.pos);hurt(swat,100,'a club',V(),'player');check(loot.near(player)?.kind==='gun'&&!run.gun,'SWAT death did not leave a rifle to steal');collect();check(run.gun&&run.equipped==='gun'&&run.gunAmmo===30&&!bodyCarry.carried,'E did not steal gun before picking up body');const ammo=run.gunAmmo;check(!loot.collect(player)&&run.gunAmmo===ammo,'rifle looted twice');const civilian=rivals[0];civilian.pos.set(27,0,13);civilian.mesh.position.copy(civilian.pos);hurt(civilian,100,'rifle fire',V(),'player');check(loot.near(player)?.kind==='ammo','civilian did not carry ammo');collect();check(run.gunAmmo===42,'ammo pickup failed');spawnCops(1,null,false,'military');const soldier=cops.at(-1);soldier.pos.set(27,0,13);soldier.mesh.position.copy(soldier.pos);hurt(soldier,100,'test');check(loot.near(player)?.kind==='ammo','non-SWAT officer did not drop ammo');newRun();check(!run.gun&&run.gunAmmo===0&&loot.drops.length===0,'loot leaked across rounds');return {swatKillRequired:true,explicitSteal:true,ammoFromOthers:12,noDoubleLoot:true,reset:true};});
 await test('Rifle shoots real targets, respects cover and can down gunships, airlifts and vehicles',()=>{newRun();player.pos.set(27,0,12);player.mesh.position.copy(player.pos);run.gun=true;run.gunAmmo=80;equip('gun');spawnCops(1,null,false,'patrol');const victim=cops.at(-1);victim.pos.set(27,0,22);victim.mesh.position.copy(victim.pos);for(let i=0;i<3;i++){victim.invincible=0;fireRifle(victim.pos.clone().add(V(0,.9,0)));}check(!victim.alive&&run.kills===1&&run.gunAmmo===77,'rifle damage, ammo or kill credit wrong');spawnHeli();const h=helis[0];h.mesh.position.set(27,15,25);for(let i=0;i<10;i++)fireRifle(h.mesh.position);check(h.dead&&h.hp===0&&run.aircraftDown===1,'gunship was invulnerable');const score=run.score;damageAircraft(h,100);check(run.score===score,'shot-down aircraft rewarded twice');airlifts.launch();const t=airlifts.flights[0];t.mesh.position.set(40,15,25);for(let i=0;i<10;i++)fireRifle(t.mesh.position);check(t.dead&&run.aircraftDown===2,'transport was invulnerable');const troops=cops.length;airlifts.update(.1);check(cops.length===troops,'destroyed transport deployed troops');spawnVehicle(false);const v=vehicles.at(-1);v.mesh.position.set(40,0,12);for(let i=0;i<7;i++)fireRifle(v.mesh.position.clone().add(V(0,1,0)));check(v.dead,'vehicle ignored rifle fire');for(let i=0;i<300&&helis.includes(h);i++)updateHelis(1/60);check(!helis.includes(h),'shot-down gunship did not crash and clean up');const wall=breakables.find(o=>o.alive&&o.kind==='window'&&o.floor===0);const origin=wall.pos.clone().add(V(0,0,4)),hit=traceWeapon(origin,V(0,0,-1),8);check(hit&&hit.type==='object','rifle ignored structural cover');run.gunAmmo=0;fireRifle(V(0,1,0));check(run.gunAmmo===0,'empty rifle consumed negative ammo');newRun();return {actorDamage:40,gunshipHP:400,transportsShootable:true,vehiclesShootable:true,cover:true,crashCleanup:true};});
 await test('Danger HUD labels each active enemy type with its threat tier',()=>{newRun();for(const unit of Object.keys(ENEMY_TYPES))spawnCops(1,null,false,unit);updateHUD();const text=$('enemyThreats').textContent;for(const type of Object.values(ENEMY_TYPES))check(text.includes('L'+type.threat+' '+type.name),'missing enemy tier '+type.name);check(threatStatus().level===5&&$('threatName').textContent.includes('L5/5'),'danger did not reflect military units');check(document.querySelectorAll('#threatBars i.active').length===5,'danger bars incorrect');newRun();updateHUD();check(!$('enemyThreats').textContent&&$('threatName').textContent.includes('L0/5'),'threat roster did not clear');return {allEnemyTiers:true,liveRoster:true,bars:true,reset:true};});
 await test('Kills from rocks, clubs, switches, slams and civilian deaths award once',()=>{for(const weapon of ['rock','thin','heavy','ram']){newRun();player.pos.set(27,0,12);player.mesh.position.copy(player.pos);yaw=0;cameraMode='third';spawnCops(1,null,false,'patrol');const a=cops[0];a.pos.set(27,0,weapon==='rock'?18:13);a.mesh.position.copy(a.pos);a.hp=1;a.invincible=0;camera.position.set(27,1.4,10);camera.lookAt(27,1,20);camera.updateMatrixWorld(true);if(weapon==='rock'){shootStone(player,a.pos.clone().add(V(0,.9,0)),true);for(let i=0;i<35&&a.alive;i++)updateProjectiles(1/60);}else if(weapon==='ram'){keys.shift=true;playerStep(1/60);keys.shift=false;}else{run[weapon]=true;equip(weapon);attackCooldown=0;attack();}check(!a.alive&&run.kills===1&&run.policeKills===1&&run.score>0,'kill not credited: '+weapon);const score=run.score;hurt(a,100,'test',null,'player');check(run.kills===1&&run.score===score,'duplicate kill credit');}newRun();const victim=rivals[0];hurt(victim,100,'a club',V(),'player');check(run.kills===1&&run.civilianKills===1&&run.score>0,'civilian kill did not count');check(crimeReport(run).rows.some(r=>r.id==='homicide'&&r.count===1),'kill missing in crime ledger');newRun();return {weapons:4,civilians:true,score:true,noDuplicates:true};});
 await test('Bodies can be physically carried, dropped, thrown and reset',()=>{newRun();player.pos.set(27,0,12);player.mesh.position.copy(player.pos);yaw=0;spawnCops(1,null,false,'patrol');const a=cops[0];a.pos.set(27,0,13);a.mesh.position.copy(a.pos);hurt(a,100,'a club',V(),'player');check(bodyCarry.near()===a&&bodyCarry.interact()&&bodyCarry.carried===a,'body pickup failed');for(let i=0;i<90;i++){bodyCarry.update(1/60);fx.update(1/60);}check(a.rag.pelvisPosition.distanceTo(player.pos.clone().add(V(0,1.4,1.1)))<.5,'held body did not follow');check(bodyCarry.interact()&&!bodyCarry.carried&&!a.rag.hold,'drop retained constraint');bodyCarry.interact();check(bodyCarry.carried===a,'could not pick up again');const start=a.rag.pelvisPosition.clone();attack();check(!bodyCarry.carried&&a.rag.lookup.hips.body.velocity.z>10,'attack did not throw body');const victim=rivals[0];victim.pos.copy(start).add(V(0,-.9,2));victim.mesh.position.copy(victim.pos);victim.hp=1;victim.invincible=0;for(let i=0;i<20&&victim.alive;i++){fx.update(1/60);bodyCarry.update(1/60);}check(!victim.alive&&run.kills===2,'thrown body failed damage or kill credit');newRun();check(!bodyCarry.carried&&physics.counts.ragdolls===0,'body state leaked into reset');return {pickup:true,physicalHold:true,drop:true,throwKills:true,reset:true};});
 await test('Third-person facing follows camera yaw while strafing, reversing and crossing angle wrap',()=>{newRun();cameraMode='third';player.pos.set(27,0,12);yaw=Math.PI-.02;player.mesh.rotation.y=-Math.PI+.02;for(let i=0;i<30;i++)moveActor(player,1/60,V(1,0,0),3);let error=Math.atan2(Math.sin(player.mesh.rotation.y-yaw),Math.cos(player.mesh.rotation.y-yaw));check(Math.abs(error)<.03,'strafe facing or wrap snapped');yaw=.4;for(let i=0;i<45;i++)moveActor(player,1/60,V(-Math.sin(yaw),0,-Math.cos(yaw)),3);error=Math.atan2(Math.sin(player.mesh.rotation.y-yaw),Math.cos(player.mesh.rotation.y-yaw));check(Math.abs(error)<.03,'reverse movement turned away from camera');const before=yaw;updateCamera(1/60);check(yaw===before,'camera fed back into yaw');newRun();return {cameraFacing:true,reverseStrafe:true,shortestAngle:true};});
 await test('Every 500K raises speed; 1M starts recurring combined siege waves',()=>{newRun();run.score=499999;milestones(0);check(run.escalation===1&&!run.siege,'escalated early');run.score=500000;milestones(0);check(run.speedTier===1&&run.escalation===1.15&&!run.siege,'500K speed missing');run.score=1000000;milestones(0);check(run.siege&&run.speedTier===2&&run.escalation===1.3&&run.siegeWave===1,'1M siege missing');check(helis.length>=4&&airlifts.count>=2&&reinforcements.active&&reinforcements.counts.marks>=5&&SPECIALISTS.every(t=>cops.some(a=>a.unit===t)),'combined siege assets missing');const wave=run.siegeWave;milestones(0);check(run.siegeWave===wave,'siege repeated every frame');run.elapsed=run.nextSiege+.01;milestones(0);check(run.siegeWave===wave+1,'siege did not recur');run.score=2000000;milestones(0);check(run.speedTier===4&&run.escalation===1.6,'skipped score thresholds lost speed');const elapsed=run.elapsed;player.invincible=100;physicsStep(1/60);check(Math.abs(run.elapsed-elapsed-1/60)<.001,'overdrive accelerated match clock');newRun();check(run.escalation===1&&!run.siege&&run.kills===0,'escalation leaked into reset');return {step:500000,speedIncrease:'15% per step',millionPointSiege:true,recurring:true,clockRealTime:true,reset:true};});
 await test('100 damage kills every character, including shielded riot and heavy units',()=>{newRun();for(const type of Object.keys(ENEMY_TYPES)){spawnCops(1,null,false,type);const a=cops.at(-1);check(a.hp===100&&a.maxHp===100,'not 100 HP: '+type);a.invincible=100;hurt(a,100,'test',V(0,0,-1),'player');check(!a.alive&&a.hp===0,'100 damage did not kill '+type);}for(const a of rivals){a.invincible=100;hurt(a,100,'test');check(!a.alive,'rival survived');}player.invincible=100;hurt(player,100,'test');check(!player.alive&&run.died&&!run.arrested,'player survived or arrested');newRun();return {allRoles:true,player:true,rivals:true,lethalBypassesShields:true};});
 await test('Large fast cannonballs pass protected supports and kill multiple characters without stopping',()=>{newRun();const column=breakables.find(o=>o.kind==='column'&&o.floor===0),origin=V(-32,column.pos.y,column.pos.z);player.pos.set(0,0,30);spawnCops(2,null,false,'swat');const victims=cops.slice(0,2);victims.forEach((a,i)=>{a.pos.set(i?22:-22,column.pos.y-.9,column.pos.z);a.invincible=100;});const mesh=new THREE.Mesh(orbGeo,materials.metal);mesh.scale.setScalar(4.5);mesh.position.copy(origin);scene.add(mesh);const p={mesh,vel:V(110,0,0),prev:origin.clone(),life:4,damage:100,cannon:true,unstoppable:true,radius:.9,struck:new Set()};projectiles.push(p);updateProjectiles(.6);check(column.alive&&column.hp===column.maxHp,'CPU cannon damaged protected support');check(victims.every(a=>!a.alive),'piercing friendly fire or swept hit failed');check(projectiles.includes(p)&&p.mesh.position.x>30&&p.vel.x===110,'cannon stopped or slowed');newRun();return {speed:110,diameter:1.8,piercing:true,instantKill:true};});
 await test('Transport helicopters fly in, deliver mixed troops to an upper floor, then leave',()=>{newRun();player.pos.set(4,H*5,5);streamTower(true);airlifts.launch();check(airlifts.count===1&&airlifts.flights[0].mesh.position.x===100,'transport did not fly in from outside');for(let i=0;i<600&&airlifts.count;i++)airlifts.update(1/60);check(airlifts.count===0,'transport did not depart');check(cops.some(a=>a.unit==='swat')&&cops.some(a=>a.unit==='military'),'mixed squad missing');check(cops.length>=4&&cops.every(a=>floorOf(a)===5&&a.insertion&&a.pos.x>10.5),'troops not dropped at player floor');for(const a of cops)for(let i=0;i<90&&!a.grounded;i++)moveActor(a,1/60,V(),0);check(cops.every(a=>a.alive&&a.grounded&&Math.abs(a.pos.y-H*5)<.05),'troops missed landing');newRun();check(airlifts.count===0,'airlift leaked into reset');return {floor:6,mixedSquad:true,physicalLanding:true,departure:true,reset:true};});
 await test('Insane starts at maximum response with faster pressure and no healing',()=>{settings.gameMode='insane';newRun();check(run.threat===5&&reinforcements.active&&helis.length===12&&reinforcements.counts.tanks===6,'Insane swarm not immediate');check(SPECIALISTS.every(type=>cops.some(a=>a.unit===type)),'specialist roster missing');for(let i=0;i<30;i++)spawnHeli();check(helis.length===16,'helicopter cap incorrect');check(config().copSpeed>DIFFICULTIES.extreme.copSpeed&&config().waves<DIFFICULTIES.extreme.waves,'Insane not faster');player.hp=70;player.lastHit=-100;playerStep(1/60);check(player.hp===70,'Insane regenerated health');settings.gameMode='regular';newRun();return {maximumResponse:true,passiveHealing:false,initialHelicopters:12,maxHelicopters:16,tanks:6,specialistTypes:6};});
 await test('Expanded prop roster has distinct meshes, damage and scoring',()=>{newRun();const kinds=['chair','monitor','printer','bookshelf','locker','vending','barrel','hydrant','bench','planter','server','toolbox','extinguisher','aircon'];for(const kind of kinds){const o=breakables.find(o=>o.kind===kind);check(o&&o.mesh.children.length>=2&&o.hp>0&&o.score>0,'missing prop '+kind);ray.set(o.pos.clone().add(V(0,0,3)),V(0,0,-1));ray.far=5;check(ray.intersectObject(o.mesh,false).length>0,'prop aiming proxy failed '+kind);}ray.far=Infinity;const server=breakables.find(o=>o.kind==='server'),before=run.destroyed;hitObject(server,9999,'player','heavy');check(!server.alive&&run.destroyed===before+1,'new prop did not score');check(!physics.collapsing,'prop destruction affected structure');newRun();return {newTypes:kinds.length,damageAndScoring:true};});
 await test('Specialists heal, aim ranged attacks and use directional armor',()=>{newRun();for(const type of SPECIALISTS)spawnCops(1,null,false,type);check(SPECIALISTS.every(type=>cops.some(a=>a.unit===type)),'specialist missing');player.pos.set(-15,0,0);player.mesh.position.copy(player.pos);player.invincible=100;const medic=cops.find(a=>a.unit==='medic'),scout=cops.find(a=>a.unit==='scout');medic.pos.set(-24,0,0);scout.pos.set(-23,0,0);scout.hp=20;aiStep(medic,.01);check(scout.hp>20,'medic did not heal');for(const type of ['sniper','grenadier']){const a=cops.find(a=>a.unit===type);a.pos.set(-28,0,type==='sniper'?0:-6);a.mesh.position.copy(a.pos);a.think=100;a.target=player;a.lastSeen=player.pos.clone();const before=projectiles.length;aiStep(a,.01);check(projectiles.length===before&&a.shotWindup>0,'ranged attack skipped windup');aiStep(a,1.3);check(projectiles.some(p=>p.owner===a&&(type==='sniper'?p.bullet:p.grenade)),'specialist did not fire '+type);}const riot=cops.find(a=>a.unit==='riot');riot.mesh.rotation.y=0;riot.hp=riot.maxHp;riot.invincible=0;hurt(riot,20,'club',V(0,0,-1),'player');const front=riot.maxHp-riot.hp;riot.hp=riot.maxHp;riot.invincible=0;hurt(riot,20,'club',V(0,0,1),'player');check(riot.maxHp-riot.hp>front,'shield did not reduce frontal damage');check(ENEMY_TYPES.scout.speed>ENEMY_TYPES.juggernaut.speed&&ENEMY_TYPES.juggernaut.damage>ENEMY_TYPES.scout.damage,'specialist stats identical');newRun();return {roles:6,medicHealing:true,telegraphedProjectiles:true,directionalShield:true};});
 await test('Elevator takes projectile damage, breaks mid-ride and resets',()=>{newRun();player.pos.set(9,0,8.4);player.mesh.position.copy(player.pos);shootStone(player,elevator.object.pos.clone(),true);for(let i=0;i<20;i++)updateProjectiles(1/60);check(elevator.object.hp<900&&elevator.object.alive,'stone did not damage elevator');player.grounded=true;check(elevator.interact(),'damaged elevator stopped working');$('elevatorFloor').value='3';$('elevatorPanel').dispatchEvent(new Event('submit',{cancelable:true,bubbles:true}));elevator.update(1);check(elevator.riding,'ride did not begin');const before=run.destroyed;hitObject(elevator.object,9999,'player','heavy');check(elevator.destroyed&&!elevator.riding&&!elevator.open&&!player.grounded,'destroyed elevator retained passenger');check(!elevator.interact()&&run.destroyed===before+1,'destroyed elevator still usable or failed scoring');hitObject(elevator.object,9999,'player','heavy');check(run.destroyed===before+1,'elevator scored twice');elevator.update(1);check(elevator.floor===0,'wreck did not fall');newRun();check(elevator.object.hp===900&&!elevator.destroyed,'elevator damage leaked into retry');return {projectileDamage:true,midRideDestruction:true,oneScoreAward:true,reset:true};});
 await test('Elevator rides to a chosen floor, calls back and resets',()=>{player.pos.set(9,0,7.9);player.grounded=true;check(elevator.interact(),'elevator inaccessible');$('elevatorFloor').value='2';$('elevatorPanel').dispatchEvent(new Event('submit',{cancelable:true,bubbles:true}));check(elevator.riding,'ride never began');elevator.update(.1);check(player.pos.y<H/2,'elevator teleported');for(let i=0;i<200;i++)elevator.update(1/60);check(!elevator.riding&&Math.abs(player.pos.y-H)<.01,'wrong arrival floor');player.pos.set(9,0,7.9);player.grounded=true;check(elevator.interact(),'call inaccessible');$('elevatorFloor').value='3';$('elevatorPanel').dispatchEvent(new Event('submit',{cancelable:true,bubbles:true}));for(let i=0;i<600;i++)elevator.update(1/60);check(!elevator.riding&&Math.abs(player.pos.y-H*2)<.01,'called car failed to deliver');newRun();check(elevator.floor===0&&!elevator.riding,'elevator leaked across runs');return {speed:1.25,destination:3,callAndReset:true};});
 await test('Tower wobbles with two supports and collapses only with one or none left',()=>{newRun();const columns=byFloor[0].filter(o=>o.kind==='column');check(columns.every(o=>o.maxHp===2400),'columns not reinforced');for(const s of platforms[0])hitObject(s,99999,'player','heavy');check(!physics.collapsing,'slab damage alone caused collapse');for(const c of columns.slice(0,2))hitObject(c,99999,'player','heavy');check(!physics.collapsing&&physics.wobbling,'two supports did not hold anchored tower');const slab=platforms[2][0],before=slab.pos.clone();for(let i=0;i<60;i++)physics.step(1/60);check(slab.pos.distanceTo(before)>.005&&slab.pos.distanceTo(before)<1,'wobble failed or released tower');check(world.fallingFloors.size===0&&!physics.towerImpact(slab.pos),'anchored wobble crushed people');streamTower(true);check(physics.wobbling&&!physics.collapsing,'streaming lost stable wobble');hitObject(columns[2],99999,'player','heavy');check(physics.collapsing&&world.fallingFloors.has(1),'one remaining support did not release tower');const falling=platforms[2][0],start=falling.pos.clone();for(let i=0;i<12;i++)physics.step(1/60);check(falling.pos.distanceTo(start)>.01,'collapse did not move');spawnCops(1,null,false,'patrol');const victim=cops.at(-1);victim.pos.copy(falling.pos).add(V(0,-.85,0));victim.invincible=100;const impact=physics.towerImpact(victim.pos);check(impact,'moving building did not detect victim');hurt(victim,100,'a collapsing tower',impact,run.collapseOwner);check(!victim.alive&&run.kills===1,'building did not kill or award credit');newRun();const fresh=byFloor[0].filter(o=>o.kind==='column');for(const c of fresh)hitObject(c,99999,'player','heavy');check(physics.collapsing,'zero-support case failed');newRun();check(!physics.collapsing&&!physics.wobbling&&world.fallingFloors.size===0,'collapse/wobble leaked into retry');return {columnHP:2400,twoSupportsHold:true,oneOrZeroCollapse:true,wobble:true,crushKills:true,streaming:true,reset:true};});
 await test('Triple-A settings apply real geometry and material detail',()=>{const before={...settings};Object.assign(settings,PRESETS.aaa);applyGraphics();updateVisibility();check(scene.children.some(m=>m.userData.highDetail&&m.visible),'detailed fixtures not shown');check(world.sun.shadow.mapSize.x===4096&&materials.metal.normalScale.x>.6,'graphics controls not applied');Object.assign(settings,before);applyGraphics();return {shadowResolution:4096,detailFixtures:true};});
